import \{ ArclineClient \} from '@arcline/sdk';

const client = new ArclineClient(\{
  clientId: process.env.ARCLINE\_CLIENT\_ID,
  clientSecret: process.env.ARCLINE\_CLIENT\_SECRET,
  environment: 'production',
\});

const users = await client.users.list(\{ limit: 10 \});

import crypto from 'node:crypto';

export function verify(rawBody, signature, secret) \{
  const expected = crypto
    .createHmac('sha256', secret)
    .update(rawBody)
    .digest('hex');

  return crypto.timingSafeEqual(
    Buffer.from(signature),
    Buffer.from(expected),
  );
\}

